from networkx import Graph, girth
import networkx as nx

g = nx.Graph()
for i in range(21):
    g.add_node(i)

# Add edges to the graph such that every vertex has degree between 4 and 6
for i in range(21):
    for j in range(i+1, 21):
        if len(list(g.neighbors(i))) < 6 and len(list(g.neighbors(j))) < 6:
            g.add_edge(i, j)
            if len(list(g.neighbors(i))) == 6 or len(list(g.neighbors(j))) == 6:
                break

# Check if the girth of the graph is at least 5
if girth(g) >= 5:
    print("SATISFIABLE")
    print(list(g.edges))
else:
    print("UNSATISFIABLE")
